/**
 * Knowledge Base Manager
 *
 * Manages fashion knowledge documents, chunking, and indexing.
 * Supports bilingual content (Thai/English) and metadata filtering.
 *
 * @version 1.0.0
 * @lastUpdated 2025-12-19
 */

import { RAG_CONFIG, getRAGConfig } from './config';
import { generateEmbedding, generateBatchEmbeddings } from './embeddings';
import {
  initializeVectorStore,
  addDocuments,
  deleteDocuments,
  getDocumentCount,
  listDocumentIds,
  clearIndex,
} from './vector-store';
import type {
  KnowledgeDocument,
  KnowledgeDocumentMetadata,
  KnowledgeCategory,
  DocumentChunk,
  ChunkingConfig,
  VectorStoreEntry,
} from './types';

// Simple token estimation (4 chars ~ 1 token for English, 2 chars ~ 1 token for Thai)
function estimateTokenCount(text: string): number {
  // Detect Thai characters
  const thaiPattern = /[\u0E00-\u0E7F]/g;
  const thaiMatches = text.match(thaiPattern);
  const thaiCharCount = thaiMatches ? thaiMatches.length : 0;
  const nonThaiCharCount = text.length - thaiCharCount;

  // Thai: ~2 chars per token, English: ~4 chars per token
  return Math.ceil(thaiCharCount / 2 + nonThaiCharCount / 4);
}

/**
 * Split text into sentences
 */
function splitIntoSentences(text: string): string[] {
  // Handle both Thai and English sentence endings
  const sentencePattern = /[.!?။ฯ]+[\s\n]+|[\n]{2,}/g;
  const sentences = text.split(sentencePattern).filter((s) => s.trim().length > 0);
  return sentences.map((s) => s.trim());
}

/**
 * Chunk a document into smaller pieces with overlap
 *
 * @param document - Knowledge document to chunk
 * @param config - Chunking configuration
 * @returns Array of document chunks
 */
export function chunkDocument(
  document: KnowledgeDocument,
  config: ChunkingConfig = RAG_CONFIG.chunking
): DocumentChunk[] {
  const chunks: DocumentChunk[] = [];
  const sentences = splitIntoSentences(document.content);

  let currentChunk: string[] = [];
  let currentTokens = 0;
  let chunkIndex = 0;

  for (let i = 0; i < sentences.length; i++) {
    const sentence = sentences[i];
    const sentenceTokens = estimateTokenCount(sentence);

    // Check if adding this sentence would exceed max tokens
    if (currentTokens + sentenceTokens > config.maxTokens && currentChunk.length > 0) {
      // Create chunk from current content
      const chunkContent = currentChunk.join(' ');
      const chunkTokenCount = estimateTokenCount(chunkContent);

      // Only add if meets minimum token requirement
      if (chunkTokenCount >= config.minTokens) {
        chunks.push({
          id: `${document.id}_chunk_${chunkIndex}`,
          documentId: document.id,
          chunkIndex,
          content: chunkContent,
          contentThai: document.contentThai
            ? extractThaiChunkContent(document.contentThai, chunkIndex, chunks.length)
            : undefined,
          tokenCount: chunkTokenCount,
          metadata: document.metadata,
        });
        chunkIndex++;
      }

      // Calculate overlap - keep last N tokens worth of sentences
      const overlapSentences: string[] = [];
      let overlapTokens = 0;

      for (let j = currentChunk.length - 1; j >= 0 && overlapTokens < config.overlapTokens; j--) {

/**
 * RAG Module Type Definitions
 *
 * TypeScript interfaces for the Fashion Expert Agent RAG system.
 * Defines knowledge documents, retrieval options, and result structures.
 *
 * @version 1.0.0
 * @lastUpdated 2025-12-19
 */

/**
 * Knowledge document categories for fashion expertise
 */
export type KnowledgeCategory =
  | 'styling_rules'
  | 'color_theory'
  | 'body_types'
  | 'occasions'
  | 'thai_culture'
  | 'brand_intelligence'
  | 'seasonal_trends';

/**
 * Gender options for filtering
 */
export type GenderFilter = 'men' | 'women' | 'unisex';

/**
 * Thai seasonal options
 */
export type ThaiSeason = 'hot' | 'rainy' | 'cool' | 'all';

/**
 * Knowledge document structure for RAG indexing
 */
export interface KnowledgeDocument {
  /** Unique identifier for the document */
  id: string;

  /** Category classification for filtering */
  category: KnowledgeCategory;

  /** Human-readable title */
  title: string;

  /** Main content in English */
  content: string;

  /** Optional Thai language content for bilingual support */
  contentThai?: string;

  /** Metadata for filtering and context */
  metadata: KnowledgeDocumentMetadata;
}

/**
 * Metadata schema for knowledge documents
 */
export interface KnowledgeDocumentMetadata {
  /** Topics covered in the document */
  topics: string[];

  /** Relevant occasions (e.g., 'wedding', 'work', 'casual') */
  occasions?: string[];

  /** Target gender demographics */
  gender?: GenderFilter[];

  /** Seasonal applicability for Thai climate */
  seasonality?: ThaiSeason[];

  /** ISO date string of last update */
  lastUpdated: string;

  /** Optional source reference */
  source?: string;

  /** Optional priority weight for retrieval (higher = more important) */
  priority?: number;
}

/**
 * Options for customizing retrieval queries
 */
export interface RetrievalOptions {
  /** Number of top results to return (default: 5) */
  topK?: number;

  /** Minimum similarity threshold (0-1, default: 0.7) */
  threshold?: number;

  /** Metadata filters for narrowing results */
  filters?: RetrievalFilters;

  /** Maximum tokens for combined context (default: 1500) */
  maxTokens?: number;

  /** Whether to include bilingual content */
  includeThai?: boolean;
}

